using System.IO;using System.Text.Json;using SaarOSS.Rechnungsprogramm.Models;
namespace SaarOSS.Rechnungsprogramm.Services;
public sealed class OfferService
{
 private static readonly JsonSerializerOptions Options=new(){WriteIndented=true};private readonly string _folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SaarOSS","Rechnungsprogramm");private string PathName=>Path.Combine(_folder,"offers.json");private string Backup=>Path.Combine(_folder,"offers.backup.json");
 public OfferStore Load(){if(!File.Exists(PathName))return new();try{return JsonSerializer.Deserialize<OfferStore>(File.ReadAllText(PathName),Options)??new();}catch(Exception ex){throw new InvalidDataException("Die Angebotsdatei konnte nicht gelesen werden und wurde nicht überschrieben.",ex);}}
 public string Preview(OfferStore s,DateTime date)=>$"{s.Prefix}{(s.IncludeYear?date.Year+"-":"")}{s.NextNumber.ToString().PadLeft(s.Digits,'0')}";
 public void SaveNumbering(OfferStore s,string prefix,bool year,int digits,int next){prefix=prefix.Trim();if(string.IsNullOrWhiteSpace(prefix))throw new ArgumentException("Das Präfix darf nicht leer sein.");if(digits<3||digits>9||next<1)throw new ArgumentException("Stellenzahl oder nächste Nummer ist ungültig.");s.Prefix=prefix;s.IncludeYear=year;s.Digits=digits;s.NextNumber=next;Save(s);}
 public void SaveDraft(OfferStore s,Offer o){if(o.Status!="Entwurf")throw new InvalidOperationException("Nur Entwürfe können bearbeitet werden.");if(o.DraftNumber==0)o.DraftNumber=s.NextDraftNumber++;o.UpdatedAt=DateTimeOffset.Now;Upsert(s,o);Save(s);}
 public void Finalize(OfferStore s,Offer o,string company,string customer){if(o.Status!="Entwurf")throw new InvalidOperationException("Nur Entwürfe können abgeschlossen werden.");while(true){var n=Preview(s,o.OfferDate);if(!s.Offers.Any(x=>x.OfferNumber.Equals(n,StringComparison.OrdinalIgnoreCase))){o.OfferNumber=n;break;}s.NextNumber++;}if(o.IsSmallBusinessSnapshot){foreach(var line in o.Lines)line.VatRate=0m;if(string.IsNullOrWhiteSpace(o.SmallBusinessNoticeSnapshot))throw new InvalidOperationException("Der Kleinunternehmer-Pflichttext fehlt.");}o.CompanySnapshot=company;o.CustomerAddressSnapshot=customer;o.Status="Versendet";o.FinalizedAt=DateTimeOffset.Now;o.SentAt=DateTimeOffset.Now;s.NextNumber++;Upsert(s,o);Save(s);}
 public void SetStatus(OfferStore s,Offer o,string status){if(o.Status=="Entwurf")throw new InvalidOperationException("Das Angebot muss zuerst abgeschlossen werden.");o.Status=status;o.UpdatedAt=DateTimeOffset.Now;if(status=="Angenommen")o.AcceptedAt=DateTimeOffset.Now;if(status=="Abgelehnt")o.RejectedAt=DateTimeOffset.Now;Upsert(s,o);Save(s);}
 public void LinkInvoice(OfferStore s,Offer o,Guid id){o.CreatedInvoiceId=id;Upsert(s,o);Save(s);}
 private static void Upsert(OfferStore s,Offer o){var i=s.Offers.FindIndex(x=>x.Id==o.Id);if(i>=0)s.Offers[i]=o;else s.Offers.Add(o);}private void Save(OfferStore s){Directory.CreateDirectory(_folder);var temp=PathName+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(s,Options));if(File.Exists(PathName))File.Copy(PathName,Backup,true);File.Move(temp,PathName,true);}
}
